import React, { useState } from 'react';
import { View, Text, TouchableOpacity, TextInput,
         Switch, Alert, StyleSheet } from 'react-native';

export default function InputExample() {
  const [text, setText] = useState('');
  const [flag, setFlag] = useState(false);

  return (
    <View style={{ padding: 20, gap: 15 }}>
      {/* Text input */}
      <TextInput
        style={styles.input}
        placeholder="Type here..."
        value={text}
        onChangeText={setText}      // called on every keystroke
        onSubmitEditing={() => Alert.alert('Submitted', text)}
        keyboardType="default"       // 'numeric', 'email-address'
        returnKeyType="done"
        secureTextEntry={false}     // true for passwords
      />

      {/* Touchable button */}
      <TouchableOpacity
        style={styles.button}
        onPress={() => Alert.alert('Pressed!', `Text: ${text}`)}
        activeOpacity={0.7}        // opacity while pressing
      >
        <Text style={{ color: '#fff', fontWeight: 'bold' }}>Press Me</Text>
      </TouchableOpacity>

      {/* Toggle switch */}
      <Switch
        value={flag}
        onValueChange={setFlag}
        trackColor={{ false: '#ccc', true: '#4CAF50' }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  input: { borderWidth: 1, borderColor: '#ccc', borderRadius: 8,
           padding: 12, fontSize: 16 },
  button: { backgroundColor: '#007AFF', padding: 15,
            borderRadius: 8, alignItems: 'center' },
