import React from 'react';
import { FlatList, ScrollView, View, Text, StyleSheet } from 'react-native';

const DATA = [
  { id: '1', name: 'Alice', age: 30 },
  { id: '2', name: 'Bob', age: 25 },
  { id: '3', name: 'Carol', age: 35 },
];

// FlatList — virtualized (efficient for large lists)
function UserList() {
  return (
    <FlatList
      data={DATA}
      keyExtractor={item => item.id}    // REQUIRED — unique key per item
      renderItem={({ item, index }) => (
        <View style={styles.item}>
          <Text style={styles.name}>{item.name}</Text>
          <Text style={styles.age}>Age: {item.age}</Text>
        </View>
      )}
      ItemSeparatorComponent={() => <View style={styles.separator} />}
      ListHeaderComponent={<Text style={styles.header}>Users</Text>}
      ListEmptyComponent={<Text>No users found</Text>}
      onRefresh={() => console.log('refreshing')}
      refreshing={false}
    />
  );
}

// ScrollView — renders ALL children (use for small lists only)
function SmallList() {
  return (
    <ScrollView showsVerticalScrollIndicator={false}>
      {DATA.map(item => <Text key={item.id}>{item.name}</Text>)}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  item: { padding: 16, backgroundColor: '#fff' },
  name: { fontSize: 16, fontWeight: 'bold' },
  age: { color: '#666' },
  separator: { height: 1, backgroundColor: '#eee' },
  header: { fontSize: 20, fontWeight: 'bold', padding: 16 },
});
```

**Rule of thumb**: Use `FlatList` for data lists (virtualizes), `ScrollView` only for screens with mixed content.

