    alignItems: 'center',              // cross axis
    gap: 10,
  },
  box: { height: 100, borderRadius: 8 },
  card: {
    backgroundColor: '#fff',
    borderRadius: 12,
    padding: 16,
    shadowColor: '#000',      // iOS shadow
